// D4-05 (TD-76): the README's HNSW benchmark numbers ARE the CSV's. The block between the ann-bench
// markers is regenerated by scripts/bench-ann-readme.mjs from docs/benchmarks/ann.csv, and this test
// recomputes it and demands equality, so a figure cannot be edited by hand or left stale. It also pins what
// the CSV must carry on every row (machine, command, "not measured on 8 GB") and what the README must say
// about the recall target and the 1M attempt.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import {
  ANN_COLUMNS,
  BEGIN,
  EIGHT_GB,
  END,
  parseCsv,
  readAnnNote,
  renderAnnBench,
} from '../scripts/bench-ann-readme.mjs';

const root = join(import.meta.dirname, '..');
const readme = readFileSync(join(root, 'README.md'), 'utf8');
const csvText = readFileSync(join(root, 'docs', 'benchmarks', 'ann.csv'), 'utf8');
const rows = parseCsv(csvText);
const note = readAnnNote();

function block(): string {
  const a = readme.indexOf(BEGIN);
  const b = readme.indexOf(END);
  expect(a, 'README has the ann-bench:begin marker').toBeGreaterThanOrEqual(0);
  expect(b, 'README has the ann-bench:end marker').toBeGreaterThan(a);
  return readme.slice(a + BEGIN.length, b).trim();
}

const where = (r: Record<string, string>) =>
  `${r['data']} ${r['rows']} ${r['index_kind']} ef ${r['ef_search']} run ${r['run']}`;

describe('docs/benchmarks/ann.csv', () => {
  it('has the documented header and rows', () => {
    expect(csvText.split('\n')[0]).toBe(ANN_COLUMNS.join(','));
    expect(rows.length).toBeGreaterThan(0);
  });

  it('every row names the machine and the command, reads "not measured on 8 GB", and has generated provenance', () => {
    for (const r of rows) {
      expect(r['eight_gb'], where(r)).toBe(EIGHT_GB);
      expect(r['machine'], where(r)).toMatch(/^.+, \d+ GB$/);
      expect(r['command'], where(r)).toMatch(/npm run bench:ann$/);
      expect(r['commit'], where(r)).toMatch(/^[0-9a-f]{7,40}(-dirty)?$/);
      expect(r['date_utc'], where(r)).toMatch(/^\d{4}-\d\d-\d\dT/);
      expect(r['os'], where(r)).toMatch(/^\w+ \w+ [\d.]+$/);
      expect(r['chrome'], where(r)).toMatch(/^Chrome\/[\d.]+$/);
      expect(r['precise_memory'], where(r)).toBe('true');
      expect(r['driver'], where(r)).toBe('opfs');
      expect(['simd', 'scalar'], where(r)).toContain(r['kernel']);
      expect(['clustered', 'uniform'], where(r)).toContain(r['data']);
      expect(['flat', 'hnsw'], where(r)).toContain(r['index_kind']);
      expect(Number(r['dim']), where(r)).toBe(384);
      expect(Number(r['k']), where(r)).toBe(10);
      expect(Number(r['queries']), where(r)).toBe(200);
      for (const c of [
        'build_ms',
        'cold_open_ms',
        'query_p50_ms',
        'query_p95_ms',
        'js_heap_peak_bytes',
        'wasm_memory_bytes',
        'index_bytes',
        'storage_usage_bytes',
      ])
        expect(Number(r[c]), `${where(r)} ${c}`).toBeGreaterThan(0);
      expect(Number(r['query_p95_ms']), where(r)).toBeGreaterThanOrEqual(Number(r['query_p50_ms']));
      const recall = Number(r['recall_at_10']);
      expect(recall, where(r)).toBeGreaterThanOrEqual(0);
      expect(recall, where(r)).toBeLessThanOrEqual(1);
      if (r['index_kind'] === 'flat') {
        expect(recall, where(r)).toBe(1);
        expect(Number(r['ann_bytes']), where(r)).toBe(0);
        for (const c of ['m', 'ef_construction', 'ef_search', 'seed']) expect(r[c], c).toBe('');
      } else {
        expect(Number(r['ann_bytes']), where(r)).toBeGreaterThan(0);
        expect(Number(r['m']), where(r)).toBe(16);
        expect(Number(r['ef_construction']), where(r)).toBe(200);
        expect([32, 64, 128], where(r)).toContain(Number(r['ef_search']));
        expect(Number(r['seed']), where(r)).toBe(1);
      }
    }
    expect(
      new Set(rows.map((r) => r['commit'])).size,
      'one commit value per run of the script',
    ).toBe(1);
  });

  it('covers flat and HNSW at ef 32, 64 and 128 on clustered data (3 runs each) and one uniform run', () => {
    const big = rows.filter((r) => r['data'] === 'clustered' && Number(r['rows']) === 100000);
    const runs = (kind: string, ef = '') =>
      new Set(
        big.filter((r) => r['index_kind'] === kind && r['ef_search'] === ef).map((r) => r['run']),
      ).size;
    expect(runs('flat'), 'flat runs').toBeGreaterThanOrEqual(3);
    for (const ef of ['32', '64', '128'])
      expect(runs('hnsw', ef), `hnsw ef ${ef} runs`).toBeGreaterThanOrEqual(3);
    const uniform = rows.filter((r) => r['data'] === 'uniform' && Number(r['rows']) === 100000);
    expect(uniform.filter((r) => r['index_kind'] === 'hnsw').length).toBeGreaterThanOrEqual(3);
    expect(uniform.filter((r) => r['index_kind'] === 'flat').length).toBeGreaterThanOrEqual(1);
  });
});

describe('README HNSW benchmarks', () => {
  it('the generated block equals what the CSV (and the 1M note) renders to: numbers come from the CSV only', () => {
    expect(block()).toBe(renderAnnBench(rows, note).trim());
  });

  it('names the machine and the command, and says "not measured on 8 GB"', () => {
    expect(readme).toContain('Apple M5 Pro, 48 GB');
    expect(readme).toContain(rows[0]!['command']!);
    expect(readme).toContain('not measured on 8 GB');
  });

  it('every table row of the block ends with the 8 GB cell', () => {
    const lines = block()
      .split('\n')
      .filter((l) => l.startsWith('| ') && !l.startsWith('| ---') && !l.startsWith('| Data'));
    expect(lines.length).toBeGreaterThanOrEqual(8);
    for (const l of lines) expect(l.trimEnd().endsWith(`| ${EIGHT_GB} |`), l).toBe(true);
  });

  it('states the recall target verdict as measured, and the generator was not changed', () => {
    expect(block()).toMatch(
      /Recall target \(stated before measuring: at least 0\.90 at ef = 128 on the 100,000 x 384 clustered set\): median \d\.\d{3}, lowest run \d\.\d{3}, so the target is (met|met by the median and missed by the lowest run|MISSED)\./,
    );
    expect(block()).toContain('The generator was not changed after the numbers were seen.');
  });

  it('says whether the 1M run happened, and why', () => {
    expect(note?.oneMillion, 'the bench wrote a 1M note').toBeDefined();
    expect(block()).toContain(`1,000,000 x 384: ${note!.oneMillion!.statement}`);
  });

  it('keeps quantisation, compaction and encryption at rest "not yet"', () => {
    const b = block();
    expect(b).toContain('Quantisation, compaction and encryption at rest are not done');
  });
});
